.submit{padding:10px 1rem;background:#18a0fb;box-shadow:0 2px 10px #29394D1A;border-radius:8px;cursor:pointer;display:flex;align-items:center;z-index:100;border:none}.submit.orange{background-color:#f47f4d}.submit.orange:hover{background:#f47f4d}.submit.redOrange{background-color:#fb1e5b}.submit.redOrange:hover{background:#fb1e5b}.submit.purple{background-color:#6f6cec}.submit.purple:hover{background:#5f5de8}.submit.orangeRoyal{background-color:#f7953e}.submit.orangeRoyal:hover{background:#e68443}.submit.greenJewel{background-color:#58e60c}.submit.greenJewel span{color:#103d47}.submit.greenJewel:hover{background:#e9ffde;box-shadow:0 0 20px 0 #58e60c;border:0.5px solid #58e60c}.submit span{text-transform:capitalize;color:#fff;font-size:18px;font-style:normal;font-weight:600;line-height:140%;margin-right:10px}.submit:disabled{opacity:0.5;cursor:default}.submit:hover{background:#2495e1}@media print, screen and (max-width: 39.99875em){.submit{padding:8px 10px}.submit span{font-size:14px}}
