.container{width:100%;padding:20px;border-radius:20px;border:1px solid #e1e4e8}.title{color:#29394d;font-size:14px;font-weight:600;line-height:140%}.cardList{display:flex;flex-direction:column;gap:20px;margin-top:10px;overflow-y:auto}.card{border-radius:12px;border:0.5px dashed #b2bcc6;background:#fff}.cardContent{display:flex;gap:10px;padding:10px;height:200px}.preview{height:100%}.previewImage{width:100%;height:100%;background-color:#fafafa;object-fit:contain;border-radius:8px;border:1px solid #e1e4e8}.info{flex:1;display:flex;flex-direction:column;justify-content:space-between}.labelTitle{color:#29394d;text-overflow:ellipsis;font-size:12px;font-weight:600;line-height:120%}.details{display:flex;flex-direction:column}.detailRow{display:flex;gap:2px;color:#6d7f92;font-size:12px;font-weight:400;line-height:140%}.detailLabel{color:#666}.detailValue{color:#29394d;font-weight:500}.actions{display:flex;gap:12px;align-items:center}.buttonSecondary{padding:10px 20px;border:1px solid #d0d0d0;border-radius:8px;background-color:white;font-size:14px;font-weight:500;cursor:pointer;display:flex;align-items:center;gap:8px;transition:all 0.2s;color:#1a1a1a}.buttonSecondary:hover{background-color:#f5f5f5;border-color:#b0b0b0}.buttonIcon{display:inline-block}.deleteButton{margin-left:auto;padding:10px;border:none;border-radius:8px;background-color:transparent;color:#ff4444;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:all 0.2s}.deleteButton:hover{background-color:#fee}
