.wrapper{position:relative;min-width:298px;height:345px;display:flex;flex-direction:column;border-radius:5px;overflow:hidden;border:1px solid #f1f2f4;background:#fff;transition:all 0.3s ease-in-out}.wrapper:hover{box-shadow:0px 4px 10px 0px rgba(41,57,77,0.1)}.wrapper .banner{display:flex;flex-direction:column;justify-content:space-between;background-size:cover;background-repeat:no-repeat;background-position:center;background-color:"lightgray";height:150px;padding:8px}.wrapper .banner .bannerTop{display:flex;justify-content:space-between}.wrapper .banner .bannerBottom{display:flex;justify-content:space-between;align-items:flex-end}.wrapper .banner .label{padding:6px 10px;border-radius:100px;background:#fff;color:#18a0fb;font-size:12px;font-style:normal;font-weight:500;line-height:normal}.wrapper .banner .clientLogo{padding:2px;width:58px;height:34px;border-radius:5px;background:#fff;display:flex;justify-content:center;align-items:center}.wrapper .banner .clientLogo img{width:54px;height:30px}.wrapper .banner .mode{display:flex;align-items:center;justify-content:space-between;gap:9px;padding:9px;padding-bottom:10px;border:1px solid #fff;border-radius:50px;background:#29394db3;max-width:34px;height:34px;transition:all 0.3s ease-in-out;overflow:hidden}.wrapper .banner .mode .modeIcon{display:flex;align-items:center;justify-content:center;width:14px;height:14px;padding-bottom:1px}.wrapper .banner .mode .modeLabel{color:#fff;font-size:12px;font-weight:500;text-wrap:nowrap;text-transform:uppercase;line-height:normal}.wrapper .banner .badges{display:flex;align-items:center;gap:10px}.wrapper .banner .badge{padding:2px 10px;border-radius:5px;background:#29394db3;color:#fff;text-align:right;font-size:12px;font-style:normal;font-weight:500;line-height:140%;text-transform:lowercase}.wrapper .banner .badge.live{background:#fe3745;text-transform:uppercase}.wrapper .banner .badge.seen{background:linear-gradient(180deg, #18a0fb 0%, #06d9b1 100%)}.wrapper .details{flex-grow:1;display:flex;flex-direction:column;justify-content:space-between;padding:10px}.wrapper .details .title{height:76px;color:#29394d;font-size:16px;font-style:normal;font-weight:600;line-height:140%;cursor:pointer;transition:all 0.2s ease-in-out}.wrapper .details .title:hover{color:#3d5270;text-decoration-line:underline;text-decoration-style:solid;text-decoration-skip-ink:none;text-decoration-thickness:auto;text-underline-offset:auto;text-underline-position:from-font}.wrapper .details .infos{flex-grow:1;display:flex;flex-direction:column}.wrapper .details .infos ul li{display:flex;align-items:center;gap:8px}.wrapper .details .infos ul li span{display:flex;align-items:center;font-weight:normal;font-size:12px;color:#29394d}.wrapper .details .infos ul li span strong{font-weight:500}.wrapper .details .infos .year{display:flex;align-items:center;border-radius:5px;border:1px solid #e1e4e8;padding:2px 6px;height:15px;color:#29394d;font-size:12px;font-style:normal;font-weight:400;line-height:normal;margin-left:8px}.wrapper .details .actions{display:flex;align-items:center;justify-content:space-between}.wrapper .details .actions .action{display:flex;align-items:center;justify-content:center;gap:8px;height:36px;min-width:112px;color:#fff;font-size:14px;font-style:normal;font-weight:500;line-height:normal;text-transform:capitalize;border:none;cursor:pointer;border-radius:8px;background:#06d9b1;transition:all 0.2s ease-in-out}.wrapper .details .actions .action:hover:not(.disabled){background:#02af8e}.wrapper .details .actions .action.default{color:#6d7f92;background:#f1f2f4}.wrapper .details .actions .action.default:hover:not(.disabled){background:#e1e4e8}.wrapper .details .actions .action.red{background:#fe3745}.wrapper .details .actions .action.red:hover:not(.disabled){background:#ec1a28}.wrapper .details .actions .action.blue{background:#18a0fb}.wrapper .details .actions .action.blue:hover:not(.disabled){background:#3b8ad5}.wrapper .details .actions .action.disabled{opacity:0.8;cursor:default}.wrapper .details .actions .price{display:flex;flex-direction:row;gap:7px;align-items:center}.wrapper .details .actions .price .mainPrice{color:#29394d;font-size:18px;font-style:normal;font-weight:600;line-height:140%;white-space:nowrap}.wrapper .details .actions .price .originalPrice{position:relative;color:#fc5d2b;font-size:18px;font-style:normal;font-weight:600;line-height:140%;white-space:nowrap}.wrapper .details .actions .price .originalPrice::after{position:absolute;content:"";width:120%;height:2px;border-radius:2px;background:#fc5d2b;top:50%;right:-10%}.wrapper .details .actions .price .memberDiscount{width:85px;min-height:42px;display:flex;flex-direction:column;justify-content:center;align-items:flex-end}.wrapper .details .actions .price .memberDiscount .discountPercent{color:#6d7f92;font-size:14px;font-style:normal;font-weight:500;line-height:normal;text-align:right}.wrapper .details .actions .price .memberDiscount .discountDescription{color:#6d7f92;font-size:10px;font-style:normal;font-weight:500;line-height:normal;text-align:right}.wrapper .details .actions .registered{display:flex;align-items:center;gap:5px;color:#02af8e;font-size:12px;font-style:normal;font-weight:500;line-height:13px}.fetching .title{height:20px;width:100%;margin-bottom:2rem}.fetching li{height:1rem;width:80%;margin-bottom:8px}
