.cycleSlide .info{border-radius:5px;background:rgba(41,57,77,0.7);padding:2px 10px;color:#fff;font-size:12px;font-style:normal;font-weight:500;line-height:normal;text-transform:lowercase}.cycleSlide ul li{font-weight:normal;font-size:14px;color:#fff;line-height:normal;display:flex}.cycleSlide ul li strong{font-weight:500}.cycleSlide ul li:not(:last-child){margin-bottom:6px}.cycleSlide .counts{display:flex;gap:10px}.cycleSlide .footer{display:flex;align-items:center;gap:20px}.cycleSlide .footer .actions{display:flex;justify-content:center;align-items:center;gap:10px}.cycleSlide .icon{height:16px !important;width:16px !important}.wrapper{position:relative}.wrapper .title{display:flex;align-items:center;padding:20px 20px 40px;border-radius:14px;z-index:1;margin-bottom:-1rem;overflow:hidden;font-size:16px;font-style:normal;font-weight:600;line-height:120%;height:117px;white-space:pre-wrap}.wrapper .title.blue{color:#18a0fb;background-color:#18a0fb1a}.wrapper .title.orange{color:#f47f4d;background-color:#f47f4d1a}.wrapper .title.purple{color:#5f5de8;background:#5f5de81a}.wrapper .title.greenTeal{color:#14b7ad;background:#14b7ad1a}.wrapper .title.redOrange{color:#fb1e5b;background:#fb1e5b1a}.wrapper .slideBlock{z-index:2}@media print, screen and (max-width: 63.99875em){.cycleSlide ul li{font-size:0.75rem}.cycleSlide .footer .actions{width:100%}.cycleSlide .icon{height:14px !important;width:14px !important}}
