.switcher{--primary-color: #18a0fb;--secondary-color: #c7e8fe;cursor:pointer;display:flex}.switcher.orange{--primary-color: #f47f4d;--secondary-color: #ffe1cc}.switcher.redOrange{--primary-color: #fb1e5b;--secondary-color: #ffabc2}.switcher.purple{--primary-color: #6f6cec;--secondary-color: #d7cfff}.switcher.greenTeal{--primary-color: #14b7ad;--secondary-color: #6fd3c9}.switcher.greenJewel{--primary-color: #58e60c;--secondary-color: #e9ffde}.switcher.disabled{opacity:0.7;cursor:not-allowed}.switcher input{display:none;opacity:0}.switcher input+span:not(.checkMark){margin-right:0.3rem}.switcher input:checked+span{color:var(--primary-color)}.switcher input:checked+.checkMark,.switcher input:checked+*+.checkMark{background:var(--primary-color)}.switcher input:checked+.checkMark::after,.switcher input:checked+*+.checkMark::after{left:unset;right:3px}.switcher span{font-weight:normal;font-size:12px;line-height:14px;color:#6d7f92}.switcher .checkMark{position:relative;width:48px;height:30px;background:#dbe0e5;border-radius:20px}.switcher .checkMark::after{content:'';display:block;position:absolute;border-radius:50%;left:3px;top:50%;width:24px;height:24px;background:#fff;transition:all 0.5s ease;transform:translateY(-50%)}
