.avatar_container{display:flex;flex-direction:row;align-items:center;gap:10px;--border-color: linear-gradient(
    180deg,
    #18a0fb 0%,
    var(--second-text-color, #06d9b1) 100%
  )}.avatar_container.greenJewel{--border-color: #58e60c}.avatar_container.blueRed{--border-color: #fe5756}.avatar_container .avatar{border-radius:50%;display:grid;place-items:center;background:var(--border-color)}.avatar_container .avatar .image{margin:2px;border-radius:50%;background-color:#fff}.avatar_container .emptyAvatar{background:linear-gradient(to bottom right, #ddd, #ccc, #c5c5c5, #bbb, #b5b5b5, #aaa);display:flex;align-items:center;justify-content:center;box-shadow:0 3px 12px 1px #2C2B3F, 0 0 0 1px #2C2B3F;border-radius:50%;border:2px solid var(--border-color)}.avatar_container .emptyAvatar span{color:#fff;font-weight:bold}.avatar_container .infos{display:flex;flex-direction:column;min-width:80px}.avatar_container .name{color:#29394d;font-size:12px;font-style:normal;font-weight:500;line-height:normal}.avatar_container.darkBlue .name{color:#29394d}.avatar_container.white .name{color:#fff}.avatar_container.greenJewel .name{color:#e9ffde}.avatar_container.blueRed .name{color:#fcebeb}
