.inline{display:flex}.inline_right{width:100%}.select_group{position:relative;display:flex;align-items:center;margin-bottom:1.875rem}.select_group_large{margin-bottom:12px}.select_group_large .select button{height:44px !important}.select_group .select{position:relative;margin-right:0.625rem}.select_group .select button{width:13.25rem;height:2.125rem;background:#f8f9fa;border:1px solid #d1d5db;border-radius:14px;padding:0rem 0.813rem 0rem 0.75rem;display:flex;align-items:center;justify-content:space-between;font-weight:400;font-size:0.75rem;cursor:pointer;color:var(--text-black-color)}.select_group .select .active_btn{border:1px solid #103d47}.select_group .select .active_btn svg{transform:rotate(180deg)}.select_group .select .list{width:13.25rem;position:absolute;left:0;background:#ffffff;border:1px solid #b2bcc6;box-shadow:0px 4px 10px rgba(41,57,77,0.1);border-radius:4px;padding:0.625rem 0rem;z-index:10;margin:0}.select_group .select .list li{font-weight:400;font-size:0.75rem;height:1.875rem;padding-left:1.313rem;display:flex;align-items:center;cursor:pointer}.select_group .select .list li:hover{background-color:#f8f9fa}.input{background:#f9fafb;border:1px solid #d1d5db;color:var(--text-black-color);box-sizing:border-box;border-radius:14px;padding:9px 15px;font-weight:400;font-size:12px;line-height:14px;width:100%}.input_large{padding:14px 15px}.input:focus,.input:focus-visible{border-color:#103d47}.input.error{border:1px solid #d50000}.codeInput input{display:inline-block}.codeInput input::-webkit-inner-spin-button{-webkit-appearance:none !important;margin:0}.codeInput input:nth-child(3),.codeInput input:nth-child(6){margin-left:0.5rem}.error{color:#d50000 !important;font-size:12px;display:block;line-height:16px;margin-top:4px}
