ient(to left, #103d47 0%, rgba(16,61,71,0.8) 64.58%, rgba(16,61,71,0) 100%)}.slider_container .swiper_wrapper .speaker{display:flex;flex-direction:row;align-items:center;gap:10px}.slider_container .swiper_wrapper .speaker .avatar{border-radius:50%;display:grid;place-items:center;background:linear-gradient(180deg, #18a0fb 0%, #06d9b1 100%)}.slider_container .swiper_wrapper .speaker .avatar .image{margin:2px;border-radius:50%;background-color:#fff}.slider_container .swiper_wrapper .speaker .emptyAvatar{background:linear-gradient(to bottom right, #ddd, #ccc, #c5c5c5, #bbb, #b5b5b5, #aaa);display:flex;align-items:center;justify-content:center;box-shadow:0 3px 12px 1px rgba(44,43,63,0.1),0 0 0 1px rgba(44,43,63,0.13);border-radius:50%;border:2px solid var(--border-color)}.slider_container .swiper_wrapper .speaker .emptyAvatar span{color:#fff;font-weight:bold}.slider_container .swiper_wrapper .speaker .infos{display:flex;flex-direction:column;min-width:80px}.slider_container .swiper_wrapper .speaker .infos .name{color:#fff;font-size:12px;font-style:normal;font-weight:500;line-height:normal}
